# Homebrew formula for the paxel/tap tap — generated by the release workflow,
# which fills in the tagged version and the sha256 of each release tarball and
# pushes the result to the homebrew-tap repository as Formula/dedup.rb.
# Binary formula: it installs the prebuilt `dedup`.
class Dedup < Formula
  desc "Forensic data-inheritance triage: dedupe, diff and browse file piles"
  homepage "https://github.com/paxel/dedup-rs"
  version "0.5.0"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/paxel/dedup-rs/releases/download/v0.5.0/dedup-0.5.0-macos-arm64.tar.gz"
      sha256 "cf7e9998b24cd26088345d34e7ad4dc8c82b74cf156008120d27a24178cea5e9"
    else
      url "https://github.com/paxel/dedup-rs/releases/download/v0.5.0/dedup-0.5.0-macos-x86_64.tar.gz"
      sha256 "212ddc05aff530353040ff0487c44ecadd1eda2ed6628bed0e5db965b7c04b98"
    end
  end

  on_linux do
    url "https://github.com/paxel/dedup-rs/releases/download/v0.5.0/dedup-0.5.0-linux-x86_64.tar.gz"
    sha256 "4d985a60225b8b2fc62e75377656db55e4131ef522e6440c57375182b543af45"
  end

  def install
    bin.install "dedup"
  end

  def caveats
    <<~EOS
      Optional tools unlock extra features (the app works without them):
        ffmpeg       — video previews, filmstrips, soundtrack playback
        poppler      — PDF page rendering (Render tab)
        libreoffice  — office/legacy document page rendering
    EOS
  end

  test do
    system "#{bin}/dedup", "--help"
  end
end
